import { FinanceSummaryCardItem } from "../components/FinancesSummaryCards";

/** تبويبات المالية — العنوان أعلاه يتبع `heading` */
export const FINANCE_TABS = [
    { id: 1, label: 'كشوفات المرتب', heading: 'كشوفات المرتب' },
    { id: 2, label: 'تفاصيل الراتب الشهري', heading: 'تفاصيل الراتب الشهري' },
    { id: 3, label: 'البدلات والعلاوات', heading: 'البدلات والعلاوات والاستحقاقات المالية' },
    { id: 4, label: 'الخصومات والضريبة', heading: 'الخصومات والضريبة' },
    { id: 5, label: 'معلومات الحساب البنكي', heading: 'معلومات الحساب البنكي' },
] as const;

export function getFinanceTabHeading(activeId: number): string {
    return FINANCE_TABS.find((t) => t.id === activeId)?.heading ?? 'البدلات والعلاوات والاستحقاقات المالية';
}

export type FinancePrimaryAction =
    | { type: 'download'; label: string }
    | { type: 'editBank'; label: string };

/** زر التنزيل / طلب التعديل أعلى الصفحة حسب التبويب */
export function getFinancePrimaryAction(activeId: number): FinancePrimaryAction {
    if (activeId === 3) return { type: 'download', label: 'تنزيل تقرير البدلات' };
    if (activeId === 5) return { type: 'editBank', label: 'طلب تعديل بيانات الحساب' };
    return { type: 'download', label: 'تنزيل التقرير السنوي' };
}
