import FinancesSummaryCards from '../FinancesSummaryCards';

const ANNUAL_TAX_ROWS = [
    { year: '2025', totalIncome: 75_000, totalTaxes: 3_750 },
    { year: '2024', totalIncome: 175_000, totalTaxes: 5_750 },
    { year: '2023', totalIncome: 35_000, totalTaxes: 3_750 },
    { year: '2022', totalIncome: 45_000, totalTaxes: 3_750 },
    { year: '2021', totalIncome: 55_000, totalTaxes: 3_750 },
    { year: '2020', totalIncome: 45_000, totalTaxes: 3_750 },
];

const SUMMARY_CARDS = [
    { title: 'إجمالي المرتب (2025)', value: '5,000', unit: 'ريال' },
    { title: 'التأمينات الاجتماعية', value: '5,750', unit: 'ريال' },
    { title: 'خصومات أخرى', value: '0', unit: 'ريال' },
];

function formatMoney(n: number) {
    return n.toLocaleString('en-US');
}

export default function DeductionsAndTaxesTab() {
    return (
        <div className="w-full mt-6 space-y-6 font-cairo">
            <FinancesSummaryCards cards={SUMMARY_CARDS} />

            <div className="rounded-xl border border-[#E8E7EA] bg-white-blue-50 shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A] overflow-hidden">
                <div className="px-4 py-3 border-b border-[#E8E7EA] bg-white-blue-100/80">
                    <h3 className="text-base font-bold text-primery-blue-500">تقرير الضرائب السنوية</h3>
                </div>
                <div className="overflow-x-auto">
                    <table className="w-full min-w-[480px] text-sm">
                        <thead>
                            <tr className="bg-white-blue-100">
                                <th className="text-start px-4 py-3 font-bold text-primery-blue-500 whitespace-nowrap">
                                    السنة
                                </th>
                                <th className="text-start px-4 py-3 font-bold text-primery-blue-500 whitespace-nowrap">
                                    إجمالي الدخل
                                </th>
                                <th className="text-start px-4 py-3 font-bold text-primery-blue-500 whitespace-nowrap">
                                    إجمالي الضرائب
                                </th>
                            </tr>
                        </thead>
                        <tbody>
                            {ANNUAL_TAX_ROWS.map((row) => (
                                <tr
                                    key={row.year}
                                    className="border-t border-[#E8E7EA] text-[#625E74] hover:bg-white-blue-100/50"
                                >
                                    <td className="px-4 py-3 font-medium tabular-nums">{row.year}</td>
                                    <td className="px-4 py-3 tabular-nums">
                                        {formatMoney(row.totalIncome)} ريال
                                    </td>
                                    <td className="px-4 py-3 tabular-nums">
                                        {formatMoney(row.totalTaxes)} ريال
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    );
}
