import FinancesDetailsTable from '../FinancesDetailsTable';
import {
    PLACEHOLDER_DEDUCTIONS_ROWS,
    PLACEHOLDER_ENTITLEMENTS_ROWS,
} from '../../data/financesPlaceholderDetails';
import FinancesSummaryCards from '../FinancesSummaryCards';
import { FINANCE_TAB_PLACEHOLDER_CARDS } from '../../data/financeTabs';

export default function FinancesTabPlaceholder() {
    return (
        <div className="w-full mt-6 space-y-6 font-cairo">
          <FinancesSummaryCards cards={FINANCE_TAB_PLACEHOLDER_CARDS} />

            <FinancesDetailsTable title="تفاصيل المستحقات" rows={PLACEHOLDER_ENTITLEMENTS_ROWS} />
            <FinancesDetailsTable title="تفاصيل الخصومات" rows={PLACEHOLDER_DEDUCTIONS_ROWS} />
        </div>
    );
}
