import { cn } from '@/lib/utils';

export type FinanceSummaryCardItem = {
    title: string;
    value: string;
    unit: string;
};

type FinancesSummaryCardsProps = {
    cards: FinanceSummaryCardItem[];
    className?: string;
};

export default function FinancesSummaryCards({ cards, className }: FinancesSummaryCardsProps) {
    return (
        <div className={cn('grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-4 gap-4', className)}>
            {cards.map((card) => (
                <div
                    key={card.title}
                    className="rounded-xl border border-[#E8E7EA] bg-white-blue-50 shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A] px-5 py-4"
                >
                    <p className="text-sm text-primery-blue-500 font-semibold leading-relaxed mb-2">{card.title}</p>
                    <p className="text-xl font-bold text-primery-blue-700 tabular-nums">
                        {card.value}{' '}
                        <span className="text-base font-semibold text-[#625E74]">{card.unit}</span>
                    </p>
                </div>
            ))}
        </div>
    );
}
